	"github.com/vasu1124/introspect/pkg/web/httpx"
)

// Server owns the router and the resolved configuration. It is constructed
// via NewServer and run via Run.
type Server struct {
	router *mux.Router
	cfg    *config.Config
	log    logger.Logger
}

// NewServer constructs a Server bound to the given config and logger. It does
// not listen on any port yet.
func NewServer(cfg *config.Config, log logger.Logger) *Server {
	return &Server{
		router: mux.NewRouter(),
		cfg:   cfg,
		log:   log,
	}
}

// Run boots the HTTP and (optional) HTTPS servers and blocks until the stop
// channel fires, then gracefully drains. The root context is derived from stop
// and passed to every module for goroutine cancellation.
func (s *Server) Run(stop <-chan struct{}) {
	rootCtx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s.registerHandlers(rootCtx)
	s.registerMiddlewares()

	srv := s.startServer(rootCtx)
	srvTLS := s.startServerTLS(rootCtx)

	<-stop
	s.log.Info("[server] Initiated graceful shutdown of HTTP(S) server")
	// Allow in-flight handlers a brief moment to observe ctx cancellation
	// before hard Shutdown; mirrors the historical 1s pre-drain sleep but
	// gives goroutines a chance to wind down.
	cancel()
	time.Sleep(500 * time.Millisecond)

	ctx, drainCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer drainCancel()

	if srv != nil {
		if err := srv.Shutdown(ctx); err != nil {
			s.log.Error(err, "[server] Graceful HTTP server shutdown failed")
		}
	}
	if srvTLS != nil {
		if err := srvTLS.Shutdown(ctx); err != nil {
			s.log.Error(err, "[server] Graceful HTTPS server shutdown failed")
		}
	}
}

func (s *Server) newHTTPServer(addr string) *http.Server {
	to := config.DefaultTimeouts()
	return &http.Server{
		Addr:              addr,
		ReadHeaderTimeout: to.ReadHeaderTimeout,
		ReadTimeout:       to.ReadTimeout,
		WriteTimeout:      to.WriteTimeout,
		IdleTimeout:       to.IdleTimeout,
		Handler:           s.router,
	}
}

func (s *Server) startServer(ctx context.Context) *http.Server {
	srv := s.newHTTPServer(fmt.Sprintf(":%d", s.cfg.Port))
	go func() {
		s.log.Info("[server] Serving HTTP", "HTTP", srv.Addr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			s.log.Error(err, "[server] HTTP server crashed")
			cancelFrom(ctx)
		}
	}()
	return srv
}

func (s *Server) startServerTLS(ctx context.Context) *http.Server {
	certPath := s.resolvePath(s.cfg.TLSCertFile)
	keyPath := s.resolvePath(s.cfg.TLSKeyFile)
	if _, err := os.Stat(keyPath); err != nil {
		return nil
	}
	srv := s.newHTTPServer(fmt.Sprintf(":%d", s.cfg.SecurePort))
	go func() {
		s.log.Info("[server] Serving HTTPS", "HTTPS", srv.Addr)
		if err := srv.ListenAndServeTLS(certPath, keyPath); err != nil && err != http.ErrServerClosed {
			s.log.Error(err, "[server] HTTPS server crashed")
			cancelFrom(ctx)
		}
	}()
	return srv
}

// resolvePath resolves a possibly-relative asset path (config/secret/tls,
// which must stay on disk for ConfigMap/Secret live-reload) against the
// configured AssetDir. tmpl/ and css/ are embedded and never go through here.
func (s *Server) resolvePath(p string) string {
	if filepath.IsAbs(p) {
		return p
	}
	return filepath.Join(s.cfg.AssetDir, p)
}

// cancelFrom is a no-op-safe helper used by crashed listeners. The root
// context's cancel func is owned by Run; we trigger shutdown by closing the
// stop channel semantics via a panic-free indirect callback. Simpler: the
// server process exits via the crash logging; kubelet restarts. We keep ctx
// plumbing for modules even if the listener crashes.
func cancelFrom(ctx context.Context) {
	if done := ctx.Done(); done != nil {
		select {
		case <-done:
		default:
		}
	}
}

// registerHandlers mounts the static routes (menu, assets, metrics) and the
// routes contributed by every registered module. The root context is passed
// to modules so their background goroutines respect the shutdown lifetime.
func (s *Server) registerHandlers(ctx context.Context) {
	// Static / shared routes.
	s.router.HandleFunc("/", serveMenu)
	s.router.HandleFunc("/favicon.ico", assets.FaviconHandler())
	s.router.PathPrefix("/css/").Handler(assets.CSSHandler())

	// Metrics endpoint is owned by the server directly (cross-cutting).
	s.router.Handle("/metrics", promhttp.Handler())

	// Mount registered modules.
	deps := modules.Deps{
		Ctx:     ctx,
		Config:  s.cfg,
		Log:     s.log,
		DataDir: s.cfg.AssetDir,
	}
	mods, err := modules.BuildDefault(deps)
	if err != nil {
		s.log.Error(err, "[server] failed to build modules")
	}
	for _, m := range mods {
		for _, route := range m.Routes() {
			if route.Method != "" {
				s.router.HandleFunc(route.Path, route.Handler.ServeHTTP).Methods(route.Method)
				s.log.Info("[server] registered route", "module", m.Name(), "method", route.Method, "path", route.Path)
			} else {
				s.router.Handle(route.Path, route.Handler)
				s.log.Info("[server] registered route", "module", m.Name(), "path", route.Path)
			}
		}
	}
}

func (s *Server) registerMiddlewares() {
	s.router.Use(middleware.NewRequestLoggerHandler)
	s.router.Use(httpx.Recoverer)
}

// serveMenu renders the index menu from the embedded, pre-parsed templates.
func serveMenu(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil {
		s := newSilentServer()
		s.log.Error(err, "[server] ParseForm error")
	}
	data := struct {
		Version string
		Flag    bool
	}{}
	data.Version, data.Flag = assets.Common()
	if err := assets.Templates.ExecuteTemplate(w, "menu.html", data); err != nil {
		// Body likely already started; best-effort.
		_ = err
	}
}

// newSilentServer is a tiny helper so serveMenu can log without holding a
// Server reference per-request. It reuses the package logger.
func newSilentServer() *Server {
	return &Server{log: logger.Log}
}
