	"github.com/vasu1124/introspect/pkg/operator/websocket"
	utilruntime "k8s.io/apimachinery/pkg/util/runtime"
	clientgoscheme "k8s.io/client-go/kubernetes/scheme"

	"github.com/olahol/melody"
	"github.com/vasu1124/introspect/pkg/operator/useless/controllers"
	"github.com/vasu1124/introspect/pkg/version"
	"k8s.io/apimachinery/pkg/runtime"
	controller_runtime "sigs.k8s.io/controller-runtime"
)

// Handler .
type Handler struct {
	Melody *melody.Melody
}

var (
	scheme = runtime.NewScheme()
)

func init() {
	utilruntime.Must(clientgoscheme.AddToScheme(scheme))
	utilruntime.Must(uselessmachinev1alpha1.AddToScheme(scheme))
	//+kubebuilder:scaffold:scheme
}

// New .
func New() *Handler {
	var h Handler

	h.Melody = melody.New()

	namespace, exists := os.LookupEnv("NAMESPACE")
	if !exists {
		namespace = "default"
	}

	controller_runtime.SetLogger(logger.Log)

	mgr, err := controller_runtime.NewManager(controller_runtime.GetConfigOrDie(), controller_runtime.Options{
		Scheme: scheme,
		// MetricsBindAddress:      "0", //turn off,
		LeaderElection:          true,
		LeaderElectionNamespace: namespace,
		LeaderElectionID:        "useless.introspect.actvirtual.com",
		Logger:                  controller_runtime.Log.WithName("operator"),
	})
	if err != nil {
		logger.Log.Error(err, "unable to start UselessMachine manager", "controller", "UselessMachine")
		return nil
	}

	if err = (&controllers.UselessMachineReconciler{
		Client:   mgr.GetClient(),
		Scheme:   mgr.GetScheme(),
		Notifier: websocket.NewNotifier(h.Melody, mgr.GetClient()),
	}).SetupWithManager(mgr); err != nil {
		logger.Log.Error(err, "[operator] unable to create controller", "controller", "UselessMachine")
		return nil
	}
	// +kubebuilder:scaffold:builder

	go func() {
		logger.Log.Info("[operator] starting manager")
		if err := mgr.Start(controller_runtime.SetupSignalHandler()); err != nil {
			logger.Log.Error(err, "[operator] problem running manager", "controller", "UselessMachine")
		}
	}()

	return &h
}

// ServeHTTP .
// This is an UI to the state of the Operator
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {

	type EnvData struct {
		Version string
		Flag    bool
	}

	data := EnvData{version.Get().GitVersion, version.GetPatchVersion()%2 == 0}

	homeTemplate, err := template.ParseFiles("tmpl/layout.html", "tmpl/operator.html")
	if err != nil {
		fmt.Fprint(w, "[operator] parsing template: ", err)
		logger.Log.Error(err, "[operator] parsing template")
		return
	}

	err = homeTemplate.Execute(w, data)
	if err != nil {
		fmt.Fprint(w, "[operator] executing template: ", err)
		logger.Log.Error(err, "[operator] executing template")
	}

}

package middleware

import (
	"bufio"
	"errors"
	"fmt"
	"net"
	"net/http"
	"time"

	"github.com/vasu1124/introspect/pkg/logger"
)

// RequestLogger .
type RequestLogger struct {
	http.ResponseWriter

	elapsedTime   time.Duration
	forwardedFor  string
	method        string
	proto         string
	remoteAddr    string
	responseBytes int64
	requestURI    string
	time          time.Time
	status        int
	userAgent     string
}

// Log .
func (r *RequestLogger) Log() {
	timestamp := r.time.Format("02/Jan/2006 03:04:05")
	requestLine := fmt.Sprintf("%s %s %s", r.method, r.requestURI, r.proto)
	// fmt.Fprintf(os.Stdout, "%s - [%s] \"%s %d %d\" %s %f\n",
	// 	r.remoteAddr, timestamp, requestLine, r.status,
	// 	r.responseBytes, r.userAgent, r.elapsedTime.Seconds())
	logger.Log.Info("[middleware] request",
		"remoteAddr", r.remoteAddr,
		"timestamp", timestamp,
		"requestLine", requestLine,
		"status", r.status,
		"responseBytes", r.responseBytes,
		"elapsedSeconds", r.elapsedTime.Seconds())
}

func (r *RequestLogger) Write(p []byte) (int, error) {
	n, err := r.ResponseWriter.Write(p)
	r.responseBytes += int64(n)
	return n, err
}

// WriteHeader .
func (r *RequestLogger) WriteHeader(status int) {
	r.status = status
	r.ResponseWriter.WriteHeader(status)
}

// RequestLoggerHandler .
type RequestLoggerHandler struct {
	handler http.Handler
}

// NewRequestLoggerHandler .
func NewRequestLoggerHandler(handler http.Handler) http.Handler {
	return &RequestLoggerHandler{
		handler: handler,
	}
}

func (h *RequestLoggerHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	rl := &RequestLogger{
		ResponseWriter: w,
		elapsedTime:    time.Duration(0),
		forwardedFor:   r.Header.Get("X-Forwarded-For"),
		method:         r.Method,
		proto:          r.Proto,
		remoteAddr:     r.RemoteAddr,
		requestURI:     r.RequestURI,
		time:           time.Time{},
		status:         http.StatusOK,
		userAgent:      r.UserAgent(),
	}

	startTime := time.Now()
	h.handler.ServeHTTP(rl, r)
	finishTime := time.Now()

	rl.time = finishTime.UTC()
	rl.elapsedTime = finishTime.Sub(startTime)
	rl.Log()
}

// Hijack is necessary for websocket
func (r *RequestLogger) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	h, ok := r.ResponseWriter.(http.Hijacker)
	if !ok {
		return nil, nil, errors.New("hijack not supported")
	}
	requestLine := fmt.Sprintf("%s %s %s", r.method, r.requestURI, r.proto)
	logger.Log.Info("[middleware] hijack enabled", "requestLine", requestLine)
	return h.Hijack()
}

