)

// Handler is the standard interface that all feature handlers must implement.
// This allows for uniform route registration and dependency injection.
type Handler interface {
	// RegisterRoutes registers the handler's HTTP routes on the given ServeMux.
	// The handler is responsible for registering all its routes (including sub-routes).
	RegisterRoutes(mux *http.ServeMux)

	// Name returns a unique identifier for this handler, used for logging/debugging.
	Name() string
}

// Middleware is a function that wraps an http.Handler for cross-cutting concerns.
type Middleware func(http.Handler) http.Handler

// MiddlewareChain applies multiple middlewares in order (first middleware wraps last).
func MiddlewareChain(h http.Handler, middlewares ...Middleware) http.Handler {
	for i := len(middlewares) - 1; i >= 0; i-- {
		h = middlewares[i](h)
	}
	return h
}

// Package assets provides embedded templates and static assets.
// All HTML templates and CSS files are embedded at compile time using go:embed.
package assets

import (
	"embed"
	"html/template"
	"io/fs"
	"net/http"
)

//go:embed tmpl/*
var templateFS embed.FS

//go:embed css/*
var cssFS embed.FS

//go:embed tmpl/favicon.ico
var faviconFS embed.FS

// Templates is the pre-parsed template set containing all HTML templates.
// Templates are parsed once at initialization for performance.
var Templates *template.Template

// CommonData holds common template data used across all pages.
type CommonData struct {
	Version string
	Flag    bool
}

// Common returns common template data with version info.
func Common() CommonData {
	return CommonData{Version, Flag}
}

func init() {
	var err error
	Templates, err = template.ParseFS(templateFS, "tmpl/*.html")
	if err != nil {
		panic("failed to parse embedded templates: " + err.Error())
	}
}

