	h.example["OSENV_EXAMPLE"] = os.Getenv("OSENV_EXAMPLE")

	configJSON, err := json.MarshalIndent(h.example, "", "  ")
	if err != nil {
		logger.Log.Error(err, "[dynconfig] json marshal error")
