	err := r.ParseForm()
	if err != nil {
		logger.Log.Error(err, "[cookie] can't parse form")
	}

	if r.Form["cookie"] != nil && r.Form["value"] != nil && r.Form["expiry"] != nil &&
		r.Form["cookie"][0] != "" && r.Form["value"][0] != "" && r.Form["expiry"][0] != "" {

		expsec, err := time.ParseDuration(r.Form["expiry"][0] + "s")
