	"github.com/vasu1124/introspect/pkg/assets"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/server"
	"github.com/vasu1124/introspect/pkg/version"
	etcdv3 "go.etcd.io/etcd/client/v3"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// Backend is the interface for guestbook storage backends.
type Backend interface {
	Insert(ctx context.Context, entry Entry) error
	Entries(ctx context.Context) ([]Entry, error)
	Close() error
	Ping(ctx context.Context) error
}

// Handler implements server.Handler for the guestbook endpoint.
type Handler struct {
	mu        sync.RWMutex
	backend   Backend
	dbtype    string
	username  string
	password  string
	config    *viper.Viper
	watcher   *fsnotify.Watcher
	cancelCtx context.CancelFunc
}

// Entry represents a guestbook entry.
type Entry struct {
	Date    time.Time
	Name    string
	Comment string
}

// New creates a new guestbook handler.
func New() *Handler {
	h := &Handler{}

	config := viper.New()
	config.SetConfigName("config")
	config.AddConfigPath("/etc/config/")
	config.AddConfigPath("./etc/config")
	if err := config.ReadInConfig(); err != nil {
		logger.Log.Error(err, "[guestbook] Fatal error config file")
	}

	h.loadSecrets()
	h.config = config

	ctx, cancel := context.WithCancel(context.Background())
	h.cancelCtx = cancel

	// Initialize backend from config
	h.readConfig(config)

	// Start config watcher
	go h.watchConfig(ctx, config)

	return h
}

func (h *Handler) loadSecrets() {
	usernamefile, _ := filepath.Abs("etc/secret/username")
	if _, err := os.Stat(usernamefile); os.IsNotExist(err) {
		usernamefile, _ = filepath.Abs("/etc/secret/username")
	}
	passwordfile, _ := filepath.Abs("etc/secret/password")
	if _, err := os.Stat(passwordfile); os.IsNotExist(err) {
		passwordfile, _ = filepath.Abs("/etc/secret/password")
	}

	if u, err := os.ReadFile(usernamefile); err == nil {
		h.username = strings.TrimSpace(string(u))
	}
	if p, err := os.ReadFile(passwordfile); err == nil {
		h.password = strings.TrimSpace(string(p))
	}
}

func (h *Handler) readConfig(config *viper.Viper) {
	if err := config.ReadInConfig(); err != nil {
		logger.Log.Error(err, "[guestbook] fatal error config file")
		return
	}

	dbtype := config.GetString("DBtype")
	if dbtype == "" {
		dbtype = "mongodb"
	}

	username := h.username
	password := h.password

	var backend Backend
	var err error

	switch dbtype {
	case "mongodb":
		backend, err = newMongoBackend(config, username, password)
	case "etcd":
		backend, err = newEtcdBackend(config, username, password)
	case "valkey":
		backend, err = newValkeyBackend(config)
	default:
		logger.Log.Error(nil, "[guestbook] Unknown DB type", "type", dbtype)
	}

	h.mu.Lock()
	if h.backend != nil {
		h.backend.Close()
	}
	h.backend = backend
	h.dbtype = dbtype
	h.mu.Unlock()

	if err != nil {
		logger.Log.Error(err, "[guestbook] Failed to init backend", "type", dbtype)
	}
}

func (h *Handler) watchConfig(ctx context.Context, config *viper.Viper) {
	watcher, err := fsnotify.NewWatcher()
	if err != nil {
		logger.Log.Error(err, "[guestbook] fsnotify error")
		return
	}
	h.watcher = watcher
	defer watcher.Close()

	watcher.Add(config.ConfigFileUsed())

	ticker := time.NewTicker(60 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case e := <-watcher.Events:
			if e.Op&fsnotify.Write == fsnotify.Write {
				logger.Log.Info("[guestbook] Config file changed", "file", e.Name)
				h.readConfig(config)
			}
			if e.Op&fsnotify.Remove == fsnotify.Remove {
				logger.Log.Info("[guestbook] Config file removed", "file", e.Name)
				watcher.Remove(e.Name)
				watcher.Add(e.Name)
				h.readConfig(config)
			}
		case err := <-watcher.Errors:
			logger.Log.Error(err, "[guestbook] Watcher error")
		case <-ticker.C:
			h.mu.RLock()
			needsReconnect := h.backend == nil
			h.mu.RUnlock()
			if needsReconnect {
				h.readConfig(config)
			}
		case <-ctx.Done():
			return
		}
	}
}

// Name implements server.Handler.
func (h *Handler) Name() string {
	return "guestbook"
}

// RegisterRoutes implements server.Handler.
func (h *Handler) RegisterRoutes(mux *http.ServeMux, ctx context.Context) {
	mux.HandleFunc("/guestbook", h.ServeHTTP)
	mux.HandleFunc("/guestbook/switch", h.SwitchHandler)
	logger.Log.Info("[guestbook] registered /guestbook and /guestbook/switch")
}

// ServeHTTP handles the guestbook request.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h.mu.RLock()
	backend := h.backend
	dbtype := h.dbtype
	h.mu.RUnlock()

	var entries []Entry

	if backend != nil {
		if r.Form == nil {
			r.ParseForm()
		}

		if r.Form["name"] != nil && r.Form["comment"] != nil &&
			r.Form["name"][0] != "" && r.Form["comment"][0] != "" {
			entry := Entry{
				Date:    time.Now(),
				Name:    r.Form["name"][0],
				Comment: r.Form["comment"][0],
			}
			if err := backend.Insert(r.Context(), entry); err != nil {
				logger.Log.Error(err, "[guestbook] insert error")
			}
		}

		entries, _ = backend.Entries(r.Context())
	}

	connected := backend != nil

	data := struct {
		assets.CommonData
		Backend   string
		Connected bool
		Entries   []Entry
	}{
		CommonData: assets.CommonData{Version: version.Version, Flag: version.Flag},
		Backend:    dbtype,
		Connected:  connected,
		Entries:    entries,
	}

	if err := assets.ExecuteTemplate(w, "guestbook.html", data); err != nil {
		logger.Log.Error(err, "[guestbook] executing template")
	}
}

// SwitchHandler handles backend switching.
func (h *Handler) SwitchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if err := r.ParseForm(); err != nil {
		logger.Log.Error(err, "[guestbook] parsing form")
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}

	backend := r.FormValue("backend")
	if backend == "" {
		http.Error(w, "Backend not specified", http.StatusBadRequest)
		return
	}

	if err := h.SwitchBackend(backend); err != nil {
		logger.Log.Error(err, "[guestbook] switching backend")
		http.Error(w, "Error switching backend", http.StatusInternalServerError)
		return
	}

	http.Redirect(w, r, "/guestbook", http.StatusSeeOther)
}

// SwitchBackend switches the database backend.
func (h *Handler) SwitchBackend(backendType string) error {
	h.mu.Lock()
	defer h.mu.Unlock()

	if backendType != "mongodb" && backendType != "etcd" && backendType != "valkey" {
		return fmt.Errorf("invalid backend: %s", backendType)
	}

	if h.backend != nil {
		if err := h.backend.Close(); err != nil {
			logger.Log.Error(err, "[guestbook] closing old backend")
		}
	}

	var backend Backend
	var err error

	switch backendType {
	case "mongodb":
		backend, err = newMongoBackend(h.config, h.username, h.password)
	case "etcd":
		backend, err = newEtcdBackend(h.config, h.username, h.password)
	case "valkey":
		backend, err = newValkeyBackend(h.config)
	}

	h.backend = backend
	h.dbtype = backendType

	if err != nil {
		logger.Log.Error(err, "[guestbook] Failed to init backend", "type", backendType)
		return err
	}

	logger.Log.Info("[guestbook] Switched backend", "backend", backendType)
	return nil
}

// Close implements graceful shutdown.
func (h *Handler) Close() error {
	if h.cancelCtx != nil {
		h.cancelCtx()
	}
	if h.watcher != nil {
		h.watcher.Close()
	}
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.backend != nil {
		return h.backend.Close()
	}
	return nil
}

// Ensure Handler implements server.Handler.
var _ server.Handler = (*Handler)(nil)

// --- MongoDB Backend ---

type mongoBackend struct {
	client  *mongo.Client
	coll    *mongo.Collection
}

func newMongoBackend(config *viper.Viper, username, password string) (*mongoBackend, error) {
	addrs := config.GetStringSlice("Addrs")
	database := config.GetString("Database")
	if database == "" {
		database = "guestbook"
	}

	if len(addrs) == 0 {
		return nil, fmt.Errorf("no MongoDB addresses in config")
	}

	uri := fmt.Sprintf("mongodb://%s", strings.Join(addrs, ","))
	clientOpts := options.Client().ApplyURI(uri)
	clientOpts.SetAuth(options.Credential{
		Username: username,
		Password: password,
	})

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	client, err := mongo.Connect(ctx, clientOpts)
	if err != nil {
		return nil, err
	}

	if err := client.Ping(ctx, nil); err != nil {
		return nil, err
	}

	coll := client.Database(database).Collection("guestbook")
	logger.Log.Info("[guestbook] Connected to MongoDB", "Addrs", addrs, "Database", database)
	return &mongoBackend{client: client, coll: coll}, nil
}

func (b *mongoBackend) Insert(ctx context.Context, entry Entry) error {
	_, err := b.coll.InsertOne(ctx, entry)
	return err
}

func (b *mongoBackend) Entries(ctx context.Context) ([]Entry, error) {
	cursor, err := b.coll.Find(ctx, bson.D{})
	if err != nil {
		return nil, err
	}
	defer cursor.Close(ctx)

	var entries []Entry
	if err := cursor.All(ctx, &entries); err != nil {
		return nil, err
	}
	return entries, nil
}

func (b *mongoBackend) Close() error {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	return b.client.Disconnect(ctx)
}

func (b *mongoBackend) Ping(ctx context.Context) error {
	return b.client.Ping(ctx, nil)
}

// --- etcd Backend ---

type etcdBackend struct {
	client *etcdv3.Client
}

func newEtcdBackend(config *viper.Viper, username, password string) (*etcdBackend, error) {
	var etcdConfig etcdv3.Config
	if err := config.Unmarshal(&etcdConfig); err != nil {
		return nil, err
	}

	etcdConfig.Username = username
	etcdConfig.Password = password

	client, err := etcdv3.New(etcdConfig)
	if err != nil {
		return nil, err
	}

	logger.Log.Info("[guestbook] Connected to Etcdv3", "Endpoints", etcdConfig.Endpoints)
	return &etcdBackend{client: client}, nil
}

func (b *etcdBackend) Insert(ctx context.Context, entry Entry) error {
	data, err := json.Marshal(entry)
	if err != nil {
		return err
	}
	_, err = b.client.Put(ctx, entry.Name, string(data))
	return err
}

func (b *etcdBackend) Entries(ctx context.Context) ([]Entry, error) {
	resp, err := b.client.Get(ctx, "", etcdv3.WithPrefix())
	if err != nil {
		return nil, err
	}

	var entries []Entry
	for _, kv := range resp.Kvs {
		var entry Entry
		if err := json.Unmarshal(kv.Value, &entry); err != nil {
			logger.Log.Error(err, "[guestbook] etcd unmarshall error")
			continue
		}
		entries = append(entries, entry)
	}
	return entries, nil
}

func (b *etcdBackend) Close() error {
	return b.client.Close()
}

func (b *etcdBackend) Ping(ctx context.Context) error {
	_, err := b.client.Status(ctx, b.client.Endpoints()[0])
	return err
}

// --- Valkey/Redis Backend ---

type valkeyBackend struct {
	client *redis.Client
}

func newValkeyBackend(config *viper.Viper) (*valkeyBackend, error) {
	addr := config.GetString("ValkeyAddr")
	if addr == "" {
		addr = "valkey:6379"
	}

	client := redis.NewClient(&redis.Options{
		Addr:     addr,
		Password: "",
		DB:       0,
	})

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := client.Ping(ctx).Err(); err != nil {
		return nil, err
	}

	logger.Log.Info("[guestbook] Connected to Valkey", "Addr", addr)
	return &valkeyBackend{client: client}, nil
}

func (b *valkeyBackend) Insert(ctx context.Context, entry Entry) error {
	data, err := json.Marshal(entry)
	if err != nil {
		return err
	}
	return b.client.LPush(ctx, "guestbook", string(data)).Err()
}

func (b *valkeyBackend) Entries(ctx context.Context) ([]Entry, error) {
	vals, err := b.client.LRange(ctx, "guestbook", 0, -1).Result()
	if err != nil {
		return nil, err
	}

	var entries []Entry
	for _, v := range vals {
		var entry Entry
		if err := json.Unmarshal([]byte(v), &entry); err != nil {
			logger.Log.Error(err, "[guestbook] valkey unmarshall error")
			continue
		}
		entries = append(entries, entry)
	}
	return entries, nil
}

func (b *valkeyBackend) Close() error {
	return b.client.Close()
}

func (b *valkeyBackend) Ping(ctx context.Context) error {
	return b.client.Ping(ctx).Err()
}

package election

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/vasu1124/introspect/pkg/assets"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/server"
	"github.com/vasu1124/introspect/pkg/version"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	clientset "k8s.io/client-go/kubernetes"
	"k8s.io/client-go/kubernetes/scheme"
	typedcorev1 "k8s.io/client-go/kubernetes/typed/core/v1"
	"k8s.io/client-go/tools/leaderelection"
	"k8s.io/client-go/tools/leaderelection/resourcelock"
	"k8s.io/client-go/tools/record"
	"sigs.k8s.io/controller-runtime/pkg/client/config"
)

// ElectionState holds the leader election state with mutex protection.
type ElectionState struct {
	mu     sync.RWMutex
	leader bool
	fail   bool
}

// Leader returns whether this instance is the leader.
func (s *ElectionState) Leader() bool {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.leader
}

// SetLeader sets the leader state.
func (s *ElectionState) SetLeader(leader bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.leader = leader
}

// Fail returns whether the election process failed.
func (s *ElectionState) Fail() bool {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.fail
}

// SetFail sets the fail state.
func (s *ElectionState) SetFail(fail bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.fail = fail
}

// NewElectionState creates a new ElectionState with default values.
func NewElectionState() *ElectionState {
	return &ElectionState{
		leader: false,
		fail:   true,
	}
}

// Handler implements server.Handler for the election endpoint.
type Handler struct {
	leaderElector *leaderelection.LeaderElector
	state         *ElectionState
	hostname      string
}

// New creates a new election handler.
func New() *Handler {
	h := &Handler{
		state: NewElectionState(),
	}

	// Get hostname
	hostname, err := os.Hostname()
	if err != nil {
		logger.Log.Error(err, "[election] Unable to get hostname")
		hostname = "unknown"
	}
	h.hostname = hostname

	// Create client config
	rc, err := config.GetConfig()
	if err != nil {
		logger.Log.Error(err, "[election] KubeConfig error")
		return h
	}
	kubeClient, err := clientset.NewForConfig(rc)
	if err != nil {
		logger.Log.Error(err, "[election] ClientSet error")
		return h
	}

	// Set up leader election
	recorder := createRecorder(kubeClient)

	leaderElectionConfig, err := makeLeaderElectionConfig(kubeClient, recorder, hostname)
	if err != nil {
		logger.Log.Error(err, "[election] leaderElectionConfig error")
		return h
	}

	leaderElectionConfig.Callbacks = leaderelection.LeaderCallbacks{
		OnStartedLeading: func(ctx context.Context) {
			h.state.SetFail(false)
			h.state.SetLeader(true)
			logger.Log.Info("[election] Got leadership")
			<-ctx.Done()
		},
		OnStoppedLeading: func() {
			h.state.SetFail(false)
			h.state.SetLeader(false)
			logger.Log.Info("[election] Lost leadership")
		},
		OnNewLeader: func(identity string) {
			h.state.SetFail(false)
			logger.Log.Info("[election] Got informed. Leadership is with", "leadership", identity)
		},
	}

	h.leaderElector, err = leaderelection.NewLeaderElector(*leaderElectionConfig)
	if err != nil {
		logger.Log.Error(err, "[election] leaderElection error")
		return h
	}

	return h
}

func makeLeaderElectionConfig(client *clientset.Clientset, recorder record.EventRecorder, hostname string) (*leaderelection.LeaderElectionConfig, error) {
	namespace, exists := os.LookupEnv("NAMESPACE")
	if !exists {
		namespace = "default"
	}

	lock := &resourcelock.LeaseLock{
		LeaseMeta: metav1.ObjectMeta{
			Name:      "election.introspect.actvirtual.com",
			Namespace: namespace,
		},
		Client: client.CoordinationV1(),
		LockConfig: resourcelock.ResourceLockConfig{
			Identity: hostname,
		},
	}

	return &leaderelection.LeaderElectionConfig{
		Lock:            lock,
		ReleaseOnCancel: true,
		LeaseDuration:   15 * time.Second,
		RenewDeadline:   10 * time.Second,
		RetryPeriod:     2 * time.Second,
	}, nil
}

func createRecorder(kubeClient *clientset.Clientset) record.EventRecorder {
	eventBroadcaster := record.NewBroadcaster()
	eventBroadcaster.StartLogging(logger.Log.Info)
	eventBroadcaster.StartRecordingToSink(&typedcorev1.EventSinkImpl{Interface: typedcorev1.New(kubeClient.CoreV1().RESTClient()).Events("")})
	return eventBroadcaster.NewRecorder(scheme.Scheme, corev1.EventSource{Component: "introspect-election"})
}

// Name implements server.Handler.
func (h *Handler) Name() string {
	return "election"
}

// RegisterRoutes implements server.Handler.
func (h *Handler) RegisterRoutes(mux *http.ServeMux, ctx context.Context) {
	mux.HandleFunc("/election", h.ServeHTTP)
	logger.Log.Info("[election] registered /election")

	// Start leader election with the server context
	go h.leaderElector.Run(ctx)
}

// ServeHTTP handles the election page request.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	data := struct {
		assets.CommonData
		Leader         bool
		Fail           bool
		LeaderElection *leaderelection.LeaderElector
		Hostname       string
	}{
		CommonData:     assets.CommonData{Version: version.Version, Flag: version.Flag},
		Leader:         h.state.Leader(),
		Fail:           h.state.Fail(),
		LeaderElection: h.leaderElector,
		Hostname:       h.hostname,
	}

	if err := assets.ExecuteTemplate(w, "leadership.html", data); err != nil {
		logger.Log.Error(err, "[election] executing template")
	}
}

// Ensure Handler implements server.Handler.
var _ server.Handler = (*Handler)(nil)

package assets

import (
	"embed"
	"html/template"
	"io/fs"
	"net/http"
)

//go:embed tmpl/*
var templateFS embed.FS

//go:embed css/*
var cssFS embed.FS

// Templates is the pre-parsed template set, initialized once at startup.
var Templates *template.Template

// CommonData contains data shared across all templates.
type CommonData struct {
	Version string
	Flag    bool
}

// Common returns the common template data (version and flag).
func Common() CommonData {
	return CommonData{Version: "0.0.0-dev", Flag: false}
}

// InitTemplates parses all embedded templates. Call once at startup.
func InitTemplates() error {
	tmpl, err := template.New("").Funcs(template.FuncMap{}).ParseFS(templateFS, "tmpl/*.html")
	if err != nil {
		return err
	}
	Templates = tmpl
	return nil
}

// CSSHandler serves embedded CSS files.
func CSSHandler() http.Handler {
	return http.StripPrefix("/css/", http.FileServer(http.FS(cssFS)))
}

// FaviconHandler serves the embedded favicon.
func FaviconHandler() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		data, err := fs.ReadFile(templateFS, "tmpl/favicon.ico")
		if err != nil {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "image/x-icon")
		w.Write(data)
	}
}

// ExecuteTemplate executes a named template with the given data.
// The data should embed CommonData for version/flag.
func ExecuteTemplate(w http.ResponseWriter, name string, data any) error {
	if Templates == nil {
		if err := InitTemplates(); err != nil {
			return err
		}
	}
	return Templates.ExecuteTemplate(w, name, data)
}

package dynconfig

import (
	"context"
	"encoding/json"
	"net/http"
	"os"

	"github.com/fsnotify/fsnotify"
	"github.com/spf13/viper"
	"github.com/vasu1124/introspect/pkg/assets"
	"github.com/vasu1124/introspect/pkg/handler"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/version"
)

// Handler implements server.Handler for the dynamic config endpoint.
type Handler struct {
	example map[string]string
}

// New creates a new dynconfig handler.
func New() *Handler {
	h := &Handler{}
	config := viper.New()

	config.SetConfigName("example")
	config.AddConfigPath("/etc/config/")
	config.AddConfigPath("./etc/config")
	if err := config.ReadInConfig(); err != nil {
		logger.Log.Error(err, "[dynconfig] Fatal error config file")
		return h
	}

	h.readConfig(config)
	go h.watchConfig(config)
	return h
}

// Name implements server.Handler.
func (h *Handler) Name() string {
	return "dynconfig"
}

// RegisterRoutes implements server.Handler.
func (h *Handler) RegisterRoutes(mux *http.ServeMux, ctx context.Context) {
	mux.HandleFunc("/dynconfig", h.ServeHTTP)
	logger.Log.Info("[dynconfig] registered /dynconfig")
}

// ServeHTTP handles the dynconfig request.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h.example["OSENV_EXAMPLE"] = os.Getenv("OSENV_EXAMPLE")

	configJSON, err := json.MarshalIndent(h.example, "", "  ")
	if err != nil {
		logger.Log.Error(err, "[dynconfig] json marshal error")
		configJSON = []byte("{}")
	}

	data := struct {
		assets.CommonData
		ConfigJSON string
	}{
		CommonData: assets.CommonData{Version: version.Version, Flag: version.Flag},
		ConfigJSON: string(configJSON),
	}

	if err := assets.ExecuteTemplate(w, "dynamicconfig.html", data); err != nil {
		logger.Log.Error(err, "[dynconfig] executing template")
	}
}

func (h *Handler) watchConfig(config *viper.Viper) {
	watcher, err := fsnotify.NewWatcher()
	if err != nil {
		logger.Log.Error(err, "[dynconfig] setup fsnotify watcher")
		return
	}
	defer watcher.Close()

	watcher.Add(config.ConfigFileUsed())

	for {
		select {
		case e := <-watcher.Events:
			if e.Op&fsnotify.Write == fsnotify.Write {
				logger.Log.Info("[dynconfig] config file changed", "file", e.Name)
				h.readConfig(config)
			}
			if e.Op&fsnotify.Remove == fsnotify.Remove {
				logger.Log.Info("[dynconfig] config file removed", "file", e.Name)
				watcher.Remove(e.Name)
				watcher.Add(e.Name)
				h.readConfig(config)
			}
		case err := <-watcher.Errors:
			logger.Log.Error(err, "[dynconfig] Watcher error")
		case <-ctx.Done():
			return
		}
	}
}

func (h *Handler) readConfig(config *viper.Viper) {
	if err := config.ReadInConfig(); err != nil {
		logger.Log.Error(err, "[dynconfig] error config file")
		return
	}
	if err := config.Unmarshal(&h.example); err != nil {
		logger.Log.Error(err, "[dynconfig] unable to unmarshal into struct")
	}
}

