func ExecuteTemplate(w http.ResponseWriter, name string, data any) error {
	if Templates == nil {
		if err := InitTemplates(); err != nil {
			return err
		}
	}
	// ParseFS uses full paths as template names (e.g., "tmpl/menu.html")
	fullName := "tmpl/" + name
	fmt.Printf("[assets] ExecuteTemplate: looking for %s\n", fullName)
	for _, t := range Templates.Templates() {
		fmt.Printf("[assets] Available: %s\n", t.Name())
	}
	return Templates.ExecuteTemplate(w, fullName, data)
}

